/**
 * Regenerate test/fixtures/codeflow-calc-health.mjs from the real CodeFlow UI.
 *
 * Usage:
 *   CODEFLOW_UI=/path/to/codeflow/index.html node generate-calc-health-fixture.mjs
 *
 * Source: https://github.com/braedonsaunders/codeflow at the revision pinned by
 * `ARG CODEFLOW_REF` in cmd/cheasee-pi/embedded/docker/codeflow/Dockerfile
 * (b0e82d127fc4990f571ebc6da6c5d9af2591aaa1). Re-run when the pin moves so the
 * acceptance test keeps scoring with upstream's own five-term function.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const uiPath = process.env.CODEFLOW_UI;
if (!uiPath) {
	console.error("Set CODEFLOW_UI=/path/to/codeflow/index.html");
	process.exit(2);
}
const html = readFileSync(uiPath, "utf8");
const s = html.indexOf("function calcHealth(data){");
const e = html.indexOf("// ===== CODEFLOW_METRICS_END =====", s);
if (s < 0 || e < 0) throw new Error("calcHealth / CODEFLOW_METRICS_END not found in index.html");
const body = html
	.slice(s, e)
	.trimEnd()
	.replace(/^function calcHealth\(data\)\{/, "export function calcHealth(data) {");

const header = `/**
 * The upstream CodeFlow health score, verbatim.
 *
 * Generated by generate-calc-health-fixture.mjs from the revision pinned by
 * \`ARG CODEFLOW_REF\` in cmd/cheasee-pi/embedded/docker/codeflow/Dockerfile
 * (b0e82d127fc4990f571ebc6da6c5d9af2591aaa1). The acceptance test scores with
 * the real five-term function the UI uses, not a re-implementation that could
 * drift from it. Re-run the generator when the pin moves.
 */
`;

writeFileSync(join(dirname(new URL(import.meta.url).pathname), "codeflow-calc-health.mjs"), header + body + "\n");
console.log(`wrote codeflow-calc-health.mjs from ${uiPath}`);
